INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('98db26bd-32b5-5931-a6fa-6d9c771764c3', '0a46bb7e-4658-5fdd-84dc-63836964e290', 1, $json${"prompt":"In the classic N-Queens backtracking solution, which three constraint sets are tracked?","multiple":false,"options":[{"id":"a","text":"Columns, positive diagonals (r+c), and negative diagonals (r−c)","is_correct":true},{"id":"b","text":"Rows, columns, and knight-move squares","is_correct":false},{"id":"c","text":"Rows, corners, and edges","is_correct":false},{"id":"d","text":"Columns only — diagonals are checked by rescanning the board","is_correct":false}],"explanation":"Placing row by row makes row conflicts impossible; O(1) membership checks on the column set and the two diagonal sets (keyed by r+c and r−c) prune invalid placements instantly."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

