VALUES ('09c76422-9f77-590e-b02c-be8f6137e568', '80f7fa2a-2cda-59e1-baef-0c9b305ddf18', 1, $json${"prompt":"When is a greedy algorithm guaranteed to produce the optimal answer?","multiple":false,"options":[{"id":"a","text":"When the problem has the greedy-choice property — each local optimum extends to a global optimum","is_correct":true},{"id":"b","text":"Whenever the input is sorted","is_correct":false},{"id":"c","text":"For every optimization problem","is_correct":false},{"id":"d","text":"Only when combined with memoization","is_correct":false}],"explanation":"Greedy works only if a locally best choice can never need to be undone (e.g. Jump Game, interval scheduling). When choices interact — like 0/1 knapsack — you need DP instead."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

