INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('2e2a4c9d-aa75-51cf-b8f8-3e43b78bdc4c', '7cf1ff49-7579-5a6d-a139-18b8e0121734', 1, $json${"prompt":"What does the CAP theorem say a distributed system must choose between during a network partition?","multiple":false,"options":[{"id":"a","text":"Consistency or availability — you cannot have both while partitioned","is_correct":true},{"id":"b","text":"Latency or throughput","is_correct":false},{"id":"c","text":"Durability or atomicity","is_correct":false},{"id":"d","text":"Nothing — modern databases avoid the trade-off entirely","is_correct":false}],"explanation":"When nodes can't communicate, you either reject requests to stay consistent (CP) or serve possibly-stale data to stay available (AP). Partition tolerance itself is non-negotiable."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('1b427a58-1c84-5f61-8682-068c7ec9b34f', '00000000-0000-0000-0000-000000000001', 'mcq', 'What is the classic failure mode of a Redis distributed lock with a TTL?', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5e55475d-fc2f-5460-899a-195ce0f9532a', '1b427a58-1c84-5f61-8682-068c7ec9b34f', 1, $json${"prompt":"What is the classic failure mode of a Redis distributed lock with a TTL?","multiple":false,"options":[{"id":"a","text":"A paused/slow client's lock expires, another client acquires it, and both run the critical section","is_correct":true},{"id":"b","text":"The lock can never expire, causing deadlock","is_correct":false},{"id":"c","text":"Redis rejects SET NX under load","is_correct":false},{"id":"d","text":"TTL locks prevent all concurrency bugs","is_correct":false}],"explanation":"If the holder stalls (GC pause, network) past the TTL, the lock is released while it still thinks it owns it. Mitigations: fencing tokens, lock renewal (watchdog), or accepting at-least-once semantics with idempotency."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('7ba3da2f-1e27-5d23-b07e-fed0785aa362', '00000000-0000-0000-0000-000000000001', 'mcq', 'In a Ticketmaster-style booking system, what prevents two users from buying t...', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
