INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('1120aaf6-2dda-5dd7-9dea-95e9d8e8528f', '7ba3da2f-1e27-5d23-b07e-fed0785aa362', 1, $json${"prompt":"In a Ticketmaster-style booking system, what prevents two users from buying the same seat?","multiple":false,"options":[{"id":"a","text":"A short-lived reservation hold (row lock or expiring hold) taken before payment completes","is_correct":true},{"id":"b","text":"Optimistically letting both pay and refunding one later, as the primary design","is_correct":false},{"id":"c","text":"Caching seat availability in the browser","is_correct":false},{"id":"d","text":"Processing all bookings on a single thread forever","is_correct":false}],"explanation":"The standard design reserves the seat atomically (SELECT ... FOR UPDATE or an expiring hold in Redis) for a payment window; if payment doesn't complete, the hold lapses and the seat returns to inventory."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

