INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('87f0f085-f5f0-5b69-b64f-686437edc7ed', '00000000-0000-0000-0000-000000000001', 'mcq', 'What makes a trie faster than a hash set for prefix queries like autocomplete?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('5406521a-ee0e-5fee-b7d2-1a7e188651e8', '87f0f085-f5f0-5b69-b64f-686437edc7ed', 1, $json${"prompt":"What makes a trie faster than a hash set for prefix queries like autocomplete?","multiple":false,"options":[{"id":"a","text":"Walking a prefix of length L visits at most L nodes, and every completion lives in that subtree","is_correct":true},{"id":"b","text":"Tries hash each prefix once and cache the result","is_correct":false},{"id":"c","text":"Tries store words sorted, enabling binary search","is_correct":false},{"id":"d","text":"Tries use less memory than hash sets in all cases","is_correct":false}],"explanation":"A hash set can only answer exact-match queries; a trie's structure IS the prefix index — descend L characters, then everything below is a valid completion. Memory is usually worse, not better."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

