INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('d90a3b51-4f7d-5094-8321-1f2aad44ce7b', '967bff6d-faab-5a6f-8145-eaa7bf8064a4', 1, $json${"prompt":"What is the first step in almost every interval problem (merge, insert, non-overlapping)?","multiple":false,"options":[{"id":"a","text":"Sort the intervals by start time","is_correct":true},{"id":"b","text":"Build an interval tree","is_correct":false},{"id":"c","text":"Convert intervals to a bitmap of covered points","is_correct":false},{"id":"d","text":"Sort by interval length, shortest first","is_correct":false}],"explanation":"After sorting by start, overlap detection becomes a single linear pass comparing each interval with the last merged one — current.start ≤ prev.end means overlap."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

