VALUES ('016c40f5-c1dc-5ca3-8d05-e98da782abe4', '00000000-0000-0000-0000-000000000001', 'mcq', 'You''re stuck on a mock-interview problem for several minutes. Best move?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4841a2c1-42f2-5d41-ac6a-ab1475b8a99a', '016c40f5-c1dc-5ca3-8d05-e98da782abe4', 1, $json${"prompt":"You're stuck on a mock-interview problem for several minutes. Best move?","multiple":false,"options":[{"id":"a","text":"Talk through what you know, name the pattern you suspect, and solve a simpler version out loud","is_correct":true},{"id":"b","text":"Go silent until you find the optimal solution","is_correct":false},{"id":"c","text":"Give up and ask for the answer","is_correct":false},{"id":"d","text":"Write code randomly hoping it compiles into insight","is_correct":false}],"explanation":"Silence is the worst signal in an interview. Verbalizing partial progress shows your debugging process and invites the interviewer's calibrated hints — which they want to give."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

