VALUES ('14c05087-98fa-59b6-8f54-4257a1ff4145', '00000000-0000-0000-0000-000000000001', 'mcq', 'Designing YouTube-scale video storage, the standard serving approach is:', 'advanced', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('a07254f1-2816-56e7-8a4f-ee853fa3c732', '14c05087-98fa-59b6-8f54-4257a1ff4145', 1, $json${"prompt":"Designing YouTube-scale video storage, the standard serving approach is:","multiple":false,"options":[{"id":"a","text":"Store transcoded segments in blob storage and serve through a CDN, keeping metadata in a database","is_correct":true},{"id":"b","text":"Store video bytes as BLOB columns in PostgreSQL","is_correct":false},{"id":"c","text":"Stream every request from the original upload server","is_correct":false},{"id":"d","text":"Keep all videos in Redis for speed","is_correct":false}],"explanation":"Video bytes belong in object storage (S3-style), delivered from CDN edges near users; databases hold only metadata (title, owner, segment manifest). Databases handle neither the size nor the bandwidth."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

