INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('51e4d266-f4dd-50c7-a087-c3a7e9b6a2be', '21363b37-c7f7-5445-8592-5949e3dd0ebc', 1, $json${"prompt":"What does company-specific preparation (Day 40) actually consist of?","multiple":false,"options":[{"id":"a","text":"Studying the company's interview format, product, tech stack, values, and preparing questions to ask them","is_correct":true},{"id":"b","text":"Memorizing the company's stock price history","is_correct":false},{"id":"c","text":"Finding leaked interview questions to memorize answers","is_correct":false},{"id":"d","text":"Emailing the interviewers in advance for hints","is_correct":false}],"explanation":"Format tells you what to drill (e.g. heavy system design vs. pure DSA); product and values let you tailor behavioral stories; your questions for them signal genuine engagement."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('8ddb598e-f381-59ab-87b9-ad2aaecead4e', '00000000-0000-0000-0000-000000000001', 'mcq', 'You blank on the optimal solution during the real interview. Best recovery?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('0f3b3819-d41f-5972-a160-e8c727457d5a', '8ddb598e-f381-59ab-87b9-ad2aaecead4e', 1, $json${"prompt":"You blank on the optimal solution during the real interview. Best recovery?","multiple":false,"options":[{"id":"a","text":"State the brute force, code it if needed, then optimize out loud — a working O(n²) beats an imaginary O(n)","is_correct":true},{"id":"b","text":"Sit silently until the optimal approach appears","is_correct":false},{"id":"c","text":"Claim you've seen the problem and ask for another","is_correct":false},{"id":"d","text":"Write the optimal solution's signature and bluff the body","is_correct":false}],"explanation":"Interviewers reward trajectory: brute force → correctness → optimization is a legitimate, hireable path. It keeps you talking, produces working code, and often the optimization emerges while explaining the bottleneck."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET content=EXCLUDED.content;

INSERT INTO questions (id, org_id, type, title, difficulty, default_points, tags, current_version, created_by)
VALUES ('34e26b3b-a0b7-50c2-bd8f-ed5afe0c7c03', '00000000-0000-0000-0000-000000000001', 'mcq', 'Which logistics checklist is correct for a remote interview day?', 'intermediate', 10, ARRAY['interview-prep','dsa','system-design','react','django','fastapi','postgresql','behavioral'], 1, '00000000-0000-0000-0000-000000000012')
ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title, difficulty=EXCLUDED.difficulty, default_points=EXCLUDED.default_points, tags=EXCLUDED.tags, updated_at=now();

INSERT INTO question_versions (id, question_id, version, content, created_by)
VALUES ('4f95d969-c68b-5614-b3af-01eefec35d93', '34e26b3b-a0b7-50c2-bd8f-ed5afe0c7c03', 1, $json${"prompt":"Which logistics checklist is correct for a remote interview day?","multiple":false,"options":[{"id":"a","text":"Test camera/mic/editor beforehand, stable connection, quiet room, water, IDs/links ready, join a few minutes early","is_correct":true},{"id":"b","text":"Join exactly on time — early looks desperate","is_correct":false},{"id":"c","text":"Keep a solutions cheat-sheet open on a second monitor","is_correct":false},{"id":"d","text":"Prepare nothing; spontaneity shows confidence","is_correct":false}],"explanation":"Day 41's logistics pass removes every controllable failure mode. A dead mic or dying laptop costs composure in the minutes that matter most — and composure is half the interview."}$json$::jsonb, '00000000-0000-0000-0000-000000000012')
